  const box=$('#targets');
  box.innerHTML=map.targets.length?map.targets.map(t=>`<div class="cmd"><div class="cmdtop"><strong>${ref(t.host.id,recordLabel(t.host))}</strong><span class="kind">${esc(t.stage)}</span></div><p>${esc(t.host.state)} · ${t.observations.length} observations${t.scopeReason?' · '+esc(t.scopeReason):''}</p><div class="target-services">${t.services.length?t.services.map(s=>`<div>${ref(s.id,`${s.port}/${s.protocol} · ${s.state} · ${s.name||'unknown'} ${s.product||''} ${s.version||''}`)}</div>`).join(''):'<span class="hint">No services recorded. Import a port scan to extend this map.</span>'}</div><p>${evidenceLinks(t.host.evidenceIds)}</p></div>`).join(''):'<div class="empty">No targets recorded yet. <button class="ref" data-open-import>Import command output</button> or <a href="#scope">discover hosts in Scope</a> to build this map.</div>';
  wireRefs(box);
