function renderWebSurvey(){const id=$('#webSurveyHost').value,box=$('#webSurvey');if(!id){box.innerHTML='<div class="empty">Choose a recorded web host to compare its saved survey results.</div>';return;}const host=findings.find(f=>f.id===id),rows=evidence.filter(e=>e.tool==='web-inventory'&&findings.some(f=>f.hostId===id&&f.evidenceIds.includes(e.id)));box.innerHTML=rows.length?rows.map(e=>{let r;try{r=JSON.parse(e.output);}catch{return '';}return `<div class="cmd"><strong>${esc(r.url)} · ${esc(date(e.observedAt))}</strong><p>${esc(r.coverage||'')}</p><p>Pages: ${(r.pages||[]).map(p=>`${esc(p.url)} → ${esc(p.status)}${p.looksLikeNotFound?' (resembles missing page)':''}`).join(' · ')||'none'}</p><p>Redirects: ${(r.redirects||[]).map(x=>`${esc(x.status)} ${esc(x.fromUrl)} → ${esc(x.toUrl)}${x.followed?'':' (blocked)'}`).join(' · ')||'none'}</p><p>Forms: ${(r.forms||[]).map(x=>`${esc(x.method)} ${esc(x.action)} [${x.fields.map(f=>esc(f.name+':'+f.type)).join(', ')}]`).join(' · ')||'none'}</p><p>Routes: ${(r.routes||[]).map(esc).join(' · ')||'none'}</p><p>Not-found baseline: ${r.notFoundBaseline?`HTTP ${esc(r.notFoundBaseline.status)} · ${esc(r.notFoundBaseline.title)}`:'not recorded'}</p><p>${evidenceLinks([e.id])}</p></div>`;}).join(''):'<div class="empty">No web inventory recorded for this host. Run its scoped “Inventory web pages and routes” check in Next checks.</div>';wireRefs(box);}
$('#webSurveyHost').onchange=renderWebSurvey;
function copyButtons(box){box.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast(b.dataset.template==='true'?'Template copied; replace placeholders before running.':'Command copied');}catch{toast('Clipboard access unavailable; select the command to copy.');}});}
function renderCatalog(){const box=$('#catalog');$('#catalogCount').textContent=`${catalog.length} catalog entries`;box.innerHTML=catalog.map(c=>{const template=/\{[^}]+\}/.test(c.command);return `<details class="cmd catalog-item"><summary class="catalog-item-toggle"><strong>${esc(c.title)}</strong></summary><div class="catalog-item-body"><p>${esc(c.when)}</p>${c.executable===false?'<p class="notice">Reference only · never automatically executed; review scope and destinations before reuse.</p>':''}${c.evidenceId?`<p>Recorded result: ${evidenceLinks([c.evidenceId])}</p>`:''}<code>${esc(c.command)}</code>${template?'<p class="notice warning">Replace the values in braces before running this command.</p>':''}<div class="toolbar"><button class="btn" data-copy="${esc(c.command)}" data-template="${template}">${template?'Copy template':'Copy'}</button></div></div></details>`;}).join('');copyButtons(box);wireRefs(box);}
function renderSuggestions(items){currentSuggestions=items;const box=$('#suggestions');box.innerHTML=items.length?items.map(s=>{const result=runResults.get(s.id);return `<div class="cmd"><div class="cmdtop"><strong>${esc(s.title)}</strong><div class="cmd-actions"><button class="btn" data-copy="${esc(s.command)}">Copy</button><button class="btn" data-edit-run="${esc(s.id)}">Edit &amp; run</button><button class="btn primary" data-run="${esc(s.id)}">Run</button></div></div><p>${esc(s.reason)}</p><code>${esc(s.command)}</code><p>Based on ${s.findingIds.map(id=>ref(id,recordLabel(findings.find(f=>f.id===id)||{title:id}))).join(' · ')}</p><p>${evidenceLinks(s.evidenceIds)}</p>${result?`<div class="run-output"><p class="status">${checkOutcome(result)}${result.imported?' · Findings updated':''}${result.warning?' · '+esc(result.warning):''}</p><code>${esc(result.command)}</code><pre>${esc(result.output||result.stderr||'No output.')}</pre></div>`:''}</div>`;}).join(''):'<div class="empty">Enter an authorized check range to see commands for recorded hosts inside it.</div>';copyButtons(box);wireRefs(box);box.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>runCheck(b,items.find(s=>s.id===b.dataset.run)));box.querySelectorAll('[data-edit-run]').forEach(b=>b.onclick=()=>editAndRun(items.find(s=>s.id===b.dataset.editRun)));}
function clearAutoPlan(message){if(autoRunning)return;autoPlan=null;$('#startAuto').disabled=true;$('#autoPlan').innerHTML='';$('#autoResults').innerHTML='';$('#autoState').textContent=message||'Select a host to preview a short run.';}
function updateAutoHosts(){updateAutonomyHosts();if(autoRunning)return;const select=$('#autoHost'),selected=select.value;const hosts=map.targets.filter(t=>t.eligible&&map.candidates.some(c=>c.hostId===t.host.id&&autoKinds.includes(c.catalogId))).map(t=>t.host);select.innerHTML=options(hosts,selected,'Select a scoped host');if(select.value!==selected&&autoPlan)clearAutoPlan('The selected host is no longer eligible. Preview again.');$('#previewAuto').disabled=!select.value;}
function updateAutonomyHosts(){const select=$('#autonomyHost'),selected=select.value;const hosts=map.targets.filter(t=>t.eligible).map(t=>t.host);select.innerHTML=options(hosts,selected,'Choose an approved host');const group=$('#autonomyGroup'),selectedGroup=[...group.selectedOptions].map(o=>o.value);group.innerHTML=hosts.map(h=>`<option value="${esc(h.id)}" ${selectedGroup.includes(h.id)?'selected':''}>${esc(recordLabel(h))}</option>`).join('');const proposal=$('#proposalHost'),chosen=proposal.value;proposal.innerHTML=options(hosts,chosen,'Choose an approved host');}
$('#autoHost').onchange=()=>{clearAutoPlan();$('#previewAuto').disabled=!$('#autoHost').value;};
$('#previewAuto').onclick=()=>{const hostId=$('#autoHost').value;if(!hostId||!checkScope()){clearAutoPlan('Select a scoped host first.');return;}const checks=map.candidates.filter(c=>c.hostId===hostId&&autoKinds.includes(c.catalogId)).sort((a,b)=>autoKinds.indexOf(a.catalogId)-autoKinds.indexOf(b.catalogId)).slice(0,3);if(!checks.length){clearAutoPlan('No short-run checks are available for this host.');return;}autoPlan={hostId,scope:JSON.stringify(checkScope()),checks:checks.map(c=>({id:c.id,title:c.title,command:c.command}))};$('#autoPlan').innerHTML=checks.map((c,i)=>`<div class="cmd"><strong>${i+1}. ${esc(c.title)}</strong><p>${esc(c.reason)}</p><code>${esc(c.command)}</code></div>`).join('');$('#autoResults').innerHTML='';$('#autoState').textContent=`${checks.length} check(s) ready. Review the commands and confirm authorization above before starting.`;$('#startAuto').disabled=false;};
$('#stopAuto').onclick=()=>{autoStop=true;$('#stopAuto').disabled=true;$('#autoState').textContent='Stop requested. Waiting for the current check to finish.';};
$('#startAuto').onclick=async()=>{
  const plan=autoPlan;
  if(!plan||autoRunning)return;
  if(!$('#checksAuthorized').checked){$('#autoState').textContent='Confirm authorization above before starting.';$('#checksAuthorized').focus();return;}
  autoRunning=true;autoStop=false;
  autoStartedAt=new Date().toISOString();
  $('#startAuto').disabled=true;$('#previewAuto').disabled=true;$('#autoHost').disabled=true;$('#stopAuto').disabled=false;
  let completed=0,stopReason='All listed checks completed.';
  try{
    await scopeSave;
    for(const check of plan.checks){
      if(autoStop){stopReason='Stopped by user.';break;}
      if(JSON.stringify(checkScope())!==plan.scope){stopReason='Target scope changed. Stopped before the next check.';break;}
      const fresh=await api('/api/workflow');
      if(autoStop){stopReason='Stopped by user.';break;}
      if(JSON.stringify(checkScope())!==plan.scope){stopReason='Target scope changed. Stopped before the next check.';break;}
      const current=fresh.candidates.find(c=>c.id===check.id&&c.hostId===plan.hostId&&c.command===check.command);
      if(!current){stopReason='A listed check or target changed. Stopped before the next check.';break;}
      $('#autoState').textContent=`Running ${completed+1} of ${plan.checks.length}: ${check.title}…`;
      autoCurrentCheck=check.command;
      const result=await post('/api/checks/run',{candidateId:check.id,authorized:true,authorizedScope:JSON.parse(plan.scope)});
      completed++;
      $('#autoResults').innerHTML+=`<div class="cmd"><strong>${esc(check.title)} · ${checkOutcome(result)}</strong><p class="status">${result.imported?'Findings updated':'No findings imported'}${result.warning?' · '+esc(result.warning):''}</p><code>${esc(result.command)}</code><pre>${esc(result.output||result.stderr||'No output.')}</pre></div>`;
      if(result.imported)await refreshFindings();
      if(result.outcome==='no-response'){stopReason='No ICMP reply. Stopped before the next check; this does not prove the host is down.';break;}
      if(result.outcome==='failed'||!result.ok||result.warning||!result.imported){stopReason=result.warning||result.stderr||'The check failed or produced no importable findings.';break;}
    }
  }catch(e){stopReason=e.message;}
  finally{
    autoRunning=false;autoPlan=null;
    autoCurrentCheck='';
    autoStartedAt=null;
    $('#stopAuto').disabled=true;$('#startAuto').disabled=true;$('#autoHost').disabled=false;
    updateAutoHosts();
    $('#autoState').textContent=`${completed} of ${plan.checks.length} check(s) finished. ${stopReason} Preview again for another run.`;
  }
};
function editAndRun(suggestion){showDialog('Edit check command',`<p class="notice">The target, program and required options stay fixed. You can change ping count (1–5), Nmap top ports (1–1000), recorded service ports or version level, and HTTP header timeout (1–20 seconds) or same-origin path. Other checks can be rerun unchanged.</p><div class="field"><label for="editedCheckCommand">Command to run</label><textarea id="editedCheckCommand" rows="4" spellcheck="false">${esc(suggestion.command)}</textarea></div><p class="status" id="editedCheckState" role="status">Review the command and confirm authorization in Next checks.</p><button class="btn primary" id="confirmEditedCheck">Run edited command</button>`);$('#confirmEditedCheck').onclick=async()=>{const command=$('#editedCheckCommand').value.trim();const button=$('#confirmEditedCheck');if(!command){$('#editedCheckState').textContent='Enter a command.';return;}if(!checkScope()||!$('#checksAuthorized').checked){$('#editedCheckState').textContent='Save a target scope and confirm check authorization in Next checks first.';return;}button.disabled=true;$('#editedCheckState').textContent='Running edited command…';const ok=await runCheck(button,suggestion,command);if(!ok&&$('#reviewDialog').open)button.disabled=false;};$('#editedCheckCommand').focus();}
async function runCheck(button,suggestion,editedCommand){if(!checkScope()){$('#suggestState').textContent='Set an authorized scope first.';location.hash='#scope';setTimeout(()=>$('#cidrs').focus(),0);return false;}if(!$('#checksAuthorized').checked){$('#suggestState').textContent='Confirm authorization before running a check.';$('#checksAuthorized').focus();return false;}button.disabled=true;$('#suggestState').textContent=`Running ${editedCommand||suggestion.command}…`;try{await scopeSave;const result=await post('/api/checks/run',{candidateId:suggestion.id,authorized:true,authorizedScope:checkScope(),...(editedCommand!==undefined?{editedCommand}:{})});runResults.set(suggestion.id,result);if(result.imported)await refreshFindings();else renderSuggestions(currentSuggestions);showDialog('Check output',`<p class="mono">${esc(result.command)}</p><p class="status">${checkOutcome(result)}${result.imported?' · Findings updated':''}${result.warning?' · '+esc(result.warning):''}</p><pre>${esc(result.output||result.stderr||'No output.')}</pre>`);$('#suggestState').textContent=result.outcome==='no-response'?'No ICMP reply; this does not prove the host is down.':result.ok?'Check finished. Review the output and updated findings.':`Check failed: ${result.stderr||'See output below.'}`;return true;}catch(e){$('#suggestState').textContent=e.message;if(editedCommand!==undefined&&$('#editedCheckState'))$('#editedCheckState').textContent=e.message;return false;}finally{button.disabled=false;}}
function renderAnalysis(result){
  const box=$('#analysisResults');
  if(!result){box.innerHTML='<div class="empty">No saved analysis. Import findings and select an analysis scope.</div>';return;}
  box.innerHTML=`<div class="cmd"><strong>${esc(result.source)}${result.model?' · '+esc(result.model):''}</strong><p>${esc(result.summary)}</p><p>${esc(date(result.generatedAt))}${result.stale?' · Findings changed since this analysis. Analyze again.':''}</p><p class="notice">${esc(result.message)}</p>${result.error?`<p class="notice warning">${esc(result.error.message)}</p>`:''}${result.warnings.map(w=>`<p class="notice warning">${esc(w)}</p>`).join('')}</div>`+result.assessments.map(a=>`<div class="cmd"><strong>${result.source==='local model'?'Model interpretation · review required':'Recorded facts'}</strong><p>${esc(a.interpretation)}</p>${a.uncertainties.map(u=>`<p class="notice">Uncertainty: ${esc(u)}</p>`).join('')}<p>${a.findingIds.map(id=>ref(id,recordLabel(findings.find(f=>f.id===id)||{title:'Previous finding'}))).join(' · ')}</p><p>${evidenceLinks(a.evidenceIds)}</p></div>`).join('');
  box.innerHTML+=(result.hypotheses||[]).map(h=>`<div class="cmd"><div class="cmdtop"><strong>${esc(h.title)}</strong><span class="kind">Model path hypothesis · review required</span></div><p>${esc(h.summary)}</p><ol>${h.steps.map(step=>`<li><p><strong>${esc(step.status)}</strong> · ${esc(step.claim)}</p><p>${step.findingIds.map(id=>ref(id,recordLabel(findings.find(f=>f.id===id)||{title:'Previous finding'}))).join(' · ')}</p><p>${evidenceLinks(step.evidenceIds)}</p></li>`).join('')}</ol>${[['Prerequisites',h.prerequisites],['Missing evidence',h.missingEvidence],['Counterevidence',h.counterevidence]].map(([label,items])=>items.length?`<strong>${label}</strong><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'').join('')}${h.investigations.length?`<strong>Proposed investigations · manual review</strong>${h.investigations.map(i=>`<div class="cmd"><p>${esc(i.objective)}</p><p>${i.hostIds.map(id=>ref(id,recordLabel(findings.find(f=>f.id===id)||{title:'Previous host'}))).join(' · ')}</p><p>Expected evidence: ${esc(i.expectedEvidence)}</p><p>Decision impact: ${esc(i.decisionImpact)}</p></div>`).join('')}`:''}</div>`).join('');
  wireRefs(box);
}
