$('#refreshAll').onclick=async()=>{const b=$('#refreshAll');b.disabled=true;try{if(await load())toast('Workspace view refreshed');}finally{b.disabled=false;}};
const draftFields={to:'draftTo',sender:'draftSender',senderName:'draftSenderName',subject:'draftSubject',body:'draftBody',notes:'draftNotes'};
function draftValues(){return Object.fromEntries(Object.entries(draftFields).map(([key,id])=>[key,$('#'+id).value]));}
function markDraftDirty(){draftDirty=true;$('#draftState').textContent='Unsaved changes';}
function draftLock(value){draftBusy=value;$('#draftForm').querySelectorAll('input,textarea,button,select').forEach(el=>el.disabled=value);$('#draftList').querySelectorAll('button').forEach(el=>el.disabled=value);}
function showDraftSources(){const address=$('#draftTo').value.trim(),contact=emailContacts.find(c=>c.address.toLowerCase()===address.toLowerCase());$('#draftContact').value=contact?.address||'';const sources=contact?.sources||(activeDraft?.to===address?activeDraft.sourceUrls:[])||[];$('#draftSources').textContent=sources.length?'Found on: '+sources.join(' · '):'You can also enter a recipient manually.';}
async function loadDraftContacts(){const data=await api('/api/email-contacts');emailContacts=data.contacts;$('#draftContact').innerHTML='<option value="">Choose a contact or enter a recipient below</option>'+emailContacts.map(c=>`<option value="${esc(c.address)}">${esc(c.address)}</option>`).join('');showDraftSources();}
function renderDraftList(){const sorted=[...emailDrafts].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));$('#draftCount').textContent=`${sorted.length} ${sorted.length===1?'draft':'drafts'}`;$('#draftList').innerHTML=sorted.length?sorted.map(d=>`<div class="item"><div class="item-left"><strong>${esc(d.subject||'Untitled draft')}</strong><small>${esc(d.to||'Recipient not set')} · ${esc(date(d.updatedAt))}</small><small>${d.sender?esc(d.sender):'Sender pending'}</small></div><div class="item-actions"><button class="btn" data-open-draft="${esc(d.id)}" ${draftBusy?'disabled':''}>Open</button><button class="btn" data-delete-draft="${esc(d.id)}" ${draftBusy?'disabled':''}>Remove</button></div></div>`).join(''):'<div class="empty">No saved drafts yet.</div>';$('#draftList').querySelectorAll('[data-open-draft]').forEach(b=>b.onclick=()=>openDraft(emailDrafts.find(d=>d.id===b.dataset.openDraft)));$('#draftList').querySelectorAll('[data-delete-draft]').forEach(b=>b.onclick=()=>removeDraft(emailDrafts.find(d=>d.id===b.dataset.deleteDraft)));}
async function refreshDrafts(){emailDrafts=(await api('/api/email-drafts')).drafts;renderDraftList();}
function openDraft(draft){if(draftBusy)return;if(draftDirty&&!window.confirm('Discard unsaved changes in the current draft?'))return;activeDraft=draft||null;Object.entries(draftFields).forEach(([key,id])=>$('#'+id).value=draft?.[key]||'');draftDirty=false;showDraftSources();$('#draftState').textContent=draft?'Saved draft · '+date(draft.updatedAt):'New draft · sender can be added later.';$('#draftSubject').focus();}
async function saveEmailDraft(){if(draftBusy||!$('#draftForm').reportValidity())return null;draftLock(true);$('#draftState').textContent='Saving draft…';try{const payload=draftValues(),data=activeDraft?await api('/api/email-drafts/'+encodeURIComponent(activeDraft.id),{method:'PATCH',body:JSON.stringify({...payload,revision:activeDraft.revision})}):await post('/api/email-drafts',payload);activeDraft=data.draft;draftDirty=false;emailDrafts=emailDrafts.filter(d=>d.id!==activeDraft.id).concat(activeDraft);renderDraftList();$('#draftState').textContent='Saved locally · '+date(activeDraft.updatedAt);showDraftSources();return activeDraft;}catch(e){$('#draftState').textContent=e.message;if(e.status===409)await refreshDrafts().catch(()=>{});return null;}finally{draftLock(false);}}
function draftText(d){return (d.sender?`From: ${d.senderName?d.senderName+' <'+d.sender+'>':d.sender}\n`:'')+(d.to?`To: ${d.to}\n`:'')+`Subject: ${d.subject}\n\n${d.body}`;}
function previewEmailDraft(){showDialog('Email preview',`<p class="notice">${$('#draftSender').value?'Draft for review.':'Sender details are pending.'}</p><pre>${esc(draftText(draftValues()))}</pre>`);}
function removeDraft(draft){if(draftBusy)return;showDialog('Remove draft',`<p>Remove ${esc(draft.subject||'Untitled draft')}?</p>${activeDraft?.id===draft.id&&draftDirty?'<p class="notice">Unsaved changes to this draft will also be discarded.</p>':''}<p class="status" id="deleteDraftError"></p><button class="btn" id="confirmRemoveDraft">Remove draft</button>`);$('#confirmRemoveDraft').onclick=async()=>{const button=$('#confirmRemoveDraft');button.disabled=true;draftLock(true);try{await api('/api/email-drafts/'+encodeURIComponent(draft.id),{method:'DELETE',body:JSON.stringify({revision:draft.revision})});emailDrafts=emailDrafts.filter(d=>d.id!==draft.id);if(activeDraft?.id===draft.id){draftDirty=false;draftLock(false);openDraft(null);}renderDraftList();$('#reviewDialog').close();toast('Draft removed');}catch(e){$('#deleteDraftError').textContent=e.message;if(e.status===409)await refreshDrafts().catch(()=>{});button.disabled=false;}finally{draftLock(false);}};}
window.addEventListener('beforeunload',event=>{if(draftDirty){event.preventDefault();event.returnValue='';}});
Object.values(draftFields).forEach(id=>$('#'+id).addEventListener('input',()=>{markDraftDirty();if(id==='draftTo')showDraftSources();}));
$('#draftContact').onchange=()=>{if($('#draftContact').value){$('#draftTo').value=$('#draftContact').value;markDraftDirty();showDraftSources();}};
$('#draftForm').onsubmit=event=>{event.preventDefault();saveEmailDraft();};
$('#newDraft').onclick=()=>openDraft(null);
$('#previewDraft').onclick=previewEmailDraft;
$('#copyDraft').onclick=async()=>{try{await navigator.clipboard.writeText(draftText(draftValues()));toast('Email draft copied');}catch{previewEmailDraft();toast('Select the preview text to copy.');}};
$('#exportDraft').onclick=async()=>{const draft=await saveEmailDraft();if(draft){const link=document.createElement('a');link.href='/api/email-drafts/'+encodeURIComponent(draft.id)+'/export';link.download='email-draft.eml';document.body.append(link);link.click();link.remove();}};
$('#generateDraft').onclick=async()=>{const values=draftValues();if(!values.notes.trim()){$('#draftState').textContent='Add a drafting brief first.';$('#draftNotes').focus();return;}draftLock(true);$('#draftState').textContent='Preparing suggested wording…';try{const proposed=await post('/api/email-drafts/generate',{brief:values.notes,subject:values.subject,body:values.body,model:$('#llmModel').value});showDialog('Suggested wording',`<p class="notice">Review this suggestion before using it. Your sender and recipient details are kept as entered.</p><pre>${esc('Subject: '+proposed.subject+'\n\n'+proposed.body)}</pre><button class="btn primary" id="useDraftWording">Use this wording</button>`);$('#useDraftWording').onclick=()=>{$('#draftSubject').value=proposed.subject;$('#draftBody').value=proposed.body;markDraftDirty();$('#reviewDialog').close();};$('#draftState').textContent='Suggestion ready for review.';}catch(e){$('#draftState').textContent=e.message+' You can continue editing manually.';}finally{draftLock(false);}};
let autonomyRuns=[],autonomyCurrent='';
let checkProposals=[];
function renderCheckProposals(){
  const box=$('#proposalList');
  box.innerHTML=checkProposals.length?checkProposals.map(p=>{
    const manual=p.kind==='manual';
    const actions=manual?`<button class="btn" data-review-proposal="${esc(p.id)}">Review ${p.reviewStatus==='approved'?'again':'command'}</button>${p.reviewStatus==='approved'&&!p.stale?`<button class="btn" data-copy-manual="${esc(p.id)}">Copy after review</button>${!p.manualEvidenceId?`<button class="btn" data-record-manual="${esc(p.id)}">Record manual result</button>`:''}`:''}`:`<button class="btn primary" data-run-proposal="${esc(p.id)}" ${p.stale?'disabled':''}>Run saved check</button>`;
    const state=p.stale?'Scope or target changed; request a new proposal.':manual?`Human review: ${esc(p.reviewStatus||'pending')} · ${p.manualEvidenceId?'Manual result recorded; reference added to catalog.':'Yagura cannot execute this command.'}`:p.lastOutcome?'Last result: '+esc(p.lastOutcome):'Not run yet.';
    return `<div class="cmd"><div class="cmdtop"><strong>${esc(p.title)} · ${esc(p.hostName||p.hostIp)}</strong><div class="cmd-actions">${actions}</div></div><p>Requested: ${esc(p.request)}</p><p>AI's reason: ${esc(p.reason)} · ${esc(p.model)} · ${esc(date(p.createdAt))}</p><code>${manual&&p.reviewStatus!=='approved'?'Open Review to inspect the full command.':esc(p.command)}</code><p class="status">${state}</p><p>${evidenceLinks(p.lastEvidenceIds||p.evidenceIds)}</p></div>`;
  }).join(''):'<div class="empty">No AI-created checks yet. Choose a host and describe one check above.</div>';
  wireRefs(box);
  box.querySelectorAll('[data-run-proposal]').forEach(button=>button.onclick=async()=>{
    if(!$('#checksAuthorized').checked){$('#proposalState').textContent='Confirm authorization in Next checks before running this proposal.';$('#checksAuthorized').focus();return;}
    button.disabled=true;$('#proposalState').textContent='Running the saved, validated check…';
    try{await scopeSave;const result=await post('/api/check-proposals/run',{proposalId:button.dataset.runProposal,authorized:true,authorizedScope:checkScope()});if(result.imported)await refreshFindings();await loadCheckProposals();showDialog('Check output',`<p class="mono">${esc(result.command)}</p><p class="status">${checkOutcome(result)}${result.imported?' · Findings updated':''}</p><pre>${esc(result.output||result.stderr||'No output.')}</pre>`);$('#proposalState').textContent=checkOutcome(result)+' · review linked evidence.';}
    catch(e){$('#proposalState').textContent=e.message;button.disabled=false;}
  });
  box.querySelectorAll('[data-review-proposal]').forEach(button=>button.onclick=()=>reviewManualProposal(checkProposals.find(p=>p.id===button.dataset.reviewProposal)));
  box.querySelectorAll('[data-copy-manual]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const current=(await api('/api/check-proposals')).proposals.find(row=>row.id===button.dataset.copyManual);if(!current||current.kind!=='manual'||current.reviewStatus!=='approved'||current.stale){$('#proposalState').textContent='Approval or scope changed; review the proposal again.';await loadCheckProposals();return;}await navigator.clipboard.writeText(current.command);toast('Reviewed command copied; run it only in an authorized environment.');}catch{$('#proposalState').textContent='Clipboard unavailable; select the reviewed command manually.';}finally{button.disabled=false;}});
  box.querySelectorAll('[data-record-manual]').forEach(button=>button.onclick=()=>recordManualResult(checkProposals.find(p=>p.id===button.dataset.recordManual)));
}
function recordManualResult(p){if(!p)return;showDialog('Record manual execution',`<p class="notice warning">Yagura will not run this command. Only record a result after you have run this exact command in an authorized environment. Review and redact the output before pasting it; the imported evidence is marked sensitive by default.</p><pre>${esc(p.command)}</pre><div class="field"><label for="manualResultOutput">Command output or redacted excerpt</label><textarea id="manualResultOutput" rows="8" maxlength="12000" placeholder="Paste the observed result"></textarea></div><label class="check"><input id="manualResultAcknowledged" type="checkbox"><span>I ran this exact reviewed command and checked its destinations.</span></label><p class="status" id="manualResultState"></p><button class="btn primary" id="saveManualResult">Save result and add reference</button>`);$('#saveManualResult').onclick=async()=>{if(!$('#manualResultAcknowledged').checked){$('#manualResultState').textContent='Confirm the manual execution first.';return;}const button=$('#saveManualResult');button.disabled=true;try{await post('/api/check-proposals/manual-result',{proposalId:p.id,expectedCommand:p.command,output:$('#manualResultOutput').value,acknowledged:true,authorizedScope:checkScope()});$('#reviewDialog').close();await refreshFindings();await loadCheckProposals();catalog=(await api('/api/commands')).commands;renderCatalog();$('#proposalState').textContent='Manual result recorded as sensitive evidence; reference added to the catalog.';}catch(e){$('#manualResultState').textContent=e.message;button.disabled=false;}};}
function reviewManualProposal(p){if(!p)return;showDialog('Human review required',`<p class="notice warning">This AI-generated command is not validated for execution by Yagura. Check every destination, argument, side effect and credential exposure. Never run it from kaliai05 against the Internet.</p><p>Approved host: ${esc(p.hostName||p.hostIp)} (${esc(p.hostIp)}) · Saved scope: ${esc((p.scope?.cidrs||[]).join(', '))}</p><pre>${esc(p.command)}</pre><label class="check"><input id="manualReviewAcknowledged" type="checkbox"><span>I personally reviewed this exact command and its destinations.</span></label><p class="status" id="manualReviewState"></p><div class="toolbar"><button class="btn primary" id="approveManualCheck">Approve for manual use</button><button class="btn" id="rejectManualCheck">Reject</button></div>`);const decide=async decision=>{if(decision==='approve'&&!$('#manualReviewAcknowledged').checked){$('#manualReviewState').textContent='Review the command and check the confirmation box first.';return;}$('#approveManualCheck').disabled=true;$('#rejectManualCheck').disabled=true;try{await post('/api/check-proposals/review',{proposalId:p.id,expectedCommand:p.command,decision,acknowledged:$('#manualReviewAcknowledged').checked,authorizedScope:checkScope()});$('#reviewDialog').close();await loadCheckProposals();catalog=(await api('/api/commands')).commands;renderCatalog();$('#proposalState').textContent=decision==='approve'?'Approved for manual use only. Yagura will not execute it.':'Manual proposal rejected.';}catch(e){$('#manualReviewState').textContent=e.message;$('#approveManualCheck').disabled=false;$('#rejectManualCheck').disabled=false;}};$('#approveManualCheck').onclick=()=>decide('approve');$('#rejectManualCheck').onclick=()=>decide('reject');}
async function loadCheckProposals(){try{checkProposals=(await api('/api/check-proposals')).proposals||[];renderCheckProposals();}catch(e){$('#proposalState').textContent=e.message;}}
$('#proposeCheck').onclick=async()=>{const hostId=$('#proposalHost').value,request=$('#proposalRequest').value.trim();if(!hostId||!checkScope()){$('#proposalState').textContent='Choose an approved host in the saved scope.';return;}if(request.length<5){$('#proposalState').textContent='Describe one check in at least five characters.';return;}const button=$('#proposeCheck');button.disabled=true;$('#proposalState').textContent='AI is preparing a check proposal…';try{await scopeSave;const result=await post('/api/check-proposals',{hostId,request,model:$('#proposalModel').value,authorizedScope:checkScope()});if(result.added){$('#proposalState').textContent=result.proposal.kind==='manual'?'Manual proposal saved. A human must review it; Yagura cannot execute it.':'Bounded proposal saved. Review the command and confirm authorization before running.';$('#proposalRequest').value='';await loadCheckProposals();}else{$('#proposalState').textContent='Not added: '+result.reason;}}catch(e){$('#proposalState').textContent=e.message;}finally{button.disabled=false;}};
function renderAutonomy(){
  const select=$('#autonomyHistory'),selected=autonomyCurrent||select.value;
  select.innerHTML=autonomyRuns.length?autonomyRuns.map(r=>`<option value="${esc(r.id)}">${esc(date(r.startedAt))} · ${esc(r.hostName||r.hostIp)} · ${esc(r.status)}</option>`).join(''):'<option value="">No runs yet</option>';
  autonomyCurrent=autonomyRuns.some(r=>r.id===selected)?selected:autonomyRuns[0]?.id||'';
  select.value=autonomyCurrent;
  const run=autonomyRuns.find(r=>r.id===autonomyCurrent),active=autonomyRuns.find(r=>['running','awaiting-approval','awaiting-host-review','awaiting-discovery'].includes(r.status));
  $('#autonomyStop').disabled=!active;
  $('#autonomyStart').disabled=!!active;
  $('#autonomyGroupStart').disabled=!!active;
  $('#autonomyDiscoverStart').disabled=!!active;
  $('#autonomyDiscoverResume').disabled=!active||!['awaiting-host-review','awaiting-discovery'].includes(active.status);
  $('#autonomyState').textContent=run?`${run.status} · ${run.hostName||run.hostIp} · ${run.events.filter(e=>e.type==='check').length}/${run.maxChecks==null?'∞':run.maxChecks} checks${run.stopReason?' · '+run.stopReason:''}`:'No AI run yet. Choose one approved host or a group to begin.';
  const box=$('#autonomyTimeline');
  const eventHtml=e=>{
    if(e.type==='decision')return `<div class="cmd"><strong>Step ${esc(e.step)} · AI decision</strong><p>${e.choice?`Chose ${esc(e.title)} · <code>${esc(e.command)}</code>`:'Chose to stop'}</p><p>Why: ${esc(e.reason)}</p>${e.expectedEvidence?`<p>Expected evidence: ${esc(e.expectedEvidence)}</p>`:''}<p>${evidenceLinks(e.evidenceIds)}</p></div>`;
    if(e.type==='check')return `<div class="cmd"><strong>Step ${esc(e.step)} · ${e.reviewed?'Human-approved check':'Check'} result: ${esc(e.outcome)}</strong>${e.hostId?`<p>Host: ${esc(recordLabel(findings.find(f=>f.id===e.hostId)||{title:e.hostId}))}</p>`:''}<p>${e.imported?'Findings imported':'No findings imported'}${e.warning?' · '+esc(e.warning):''}</p><p>Evidence: ${evidenceLinks(e.evidenceIds)||'none'}</p></div>`;
    if(e.type==='proposal')return `<div class="cmd"><strong>Proposed command · revision ${esc(e.revision)}</strong><p><code>${esc(e.command)}</code></p><p>Why: ${esc(e.reason)}</p>${e.reviewNotes?`<p>Review notes: ${esc(e.reviewNotes)}</p>`:''}${e.revisionInstruction?`<p>Human correction: ${esc(e.revisionInstruction)}</p>`:''}</div>`;
    if(e.type==='approval')return `<div class="cmd"><strong>Human approved revision ${esc(e.revision)}</strong><p><code>${esc(e.command)}</code></p></div>`;
    if(e.type==='survey')return `<div class="cmd"><strong>Baseline survey · ${esc(recordLabel(findings.find(f=>f.id===e.hostId)||{title:e.hostId}))}</strong><p>${esc(e.reason)}</p>${e.candidateId?`<p>Candidate: ${esc(e.candidateId)}</p>`:''}</div>`;
    if(e.type==='context')return `<div class="cmd"><strong>Comparison context prepared</strong><p>${esc(e.findingIds?.length||0)} findings · ${esc(e.evidenceIds?.length||0)} evidence items · ${esc(e.candidateIds?.length||0)} candidate checks${e.truncated?' · More saved context is available on request.':''}</p><p>Snapshot: <code>${esc((e.snapshotId||'').slice(0,12))}</code></p></div>`;
    if(e.type==='context-read')return `<div class="cmd"><strong>AI requested saved context</strong>${(e.operations||[]).map(o=>`<p>${esc(o.tool)}${o.hostId?' · '+esc(recordLabel(findings.find(f=>f.id===o.hostId)||{title:o.hostId})):''}${o.offset?' · offset '+esc(o.offset):''} · ${esc(o.findingIds?.length||0)} findings, ${esc(o.evidenceIds?.length||0)} evidence items, ${esc(o.candidateIds?.length||0)} candidates</p>`).join('')}</div>`;
    if(e.type==='context-repair')return `<div class="cmd"><strong>AI citation correction requested</strong><p>${esc(e.reason)}</p></div>`;
    if(e.type==='comparison')return `<div class="cmd"><strong>Cross-host comparison · ${esc(e.flags.length)} flagged</strong><p>${esc(e.reason||'Review the cited evidence and uncertainty.')}</p>${e.flags.map(f=>`<div class="finding-record"><strong>${esc(recordLabel(findings.find(x=>x.id===f.hostId)||{title:f.hostId}))}</strong><p>${esc(f.reason)}</p><p>Uncertainty: ${esc(f.uncertainty)}</p><p>${f.findingIds.map(id=>ref(id,recordLabel(findings.find(x=>x.id===id)||{title:id}))).join(' · ')}</p><p>${evidenceLinks(f.evidenceIds)}</p></div>`).join('')}${e.choice?`<p>Next catalog check: ${esc(e.choice)}</p>`:''}</div>`;
    if(e.type==='discovery')return `<div class="cmd"><strong>Discovery segment ${esc(e.cidr)}</strong><p>${esc(e.count)} host(s) found · ${esc(e.completed)}/${esc(e.total)} segments in this range</p></div>`;
    if(e.type==='dns-review')return `<div class="cmd"><strong>DNS review · ${esc(e.hostIp)}</strong><p>Approved-name candidates: ${esc((e.candidates||[]).join(', ')||'none')}${e.conflicting?' · resolver conflict':''}</p></div>`;
    if(e.type==='selection')return `<div class="cmd"><strong>Automatically selected ${esc(e.hostIds.length)} approved hosts</strong><p>${esc(e.reason)}</p><p>${e.hostIds.map(id=>ref(id,recordLabel(findings.find(f=>f.id===id)||{title:id}))).join(' · ')}</p></div>`;
    if(e.type==='pause')return `<div class="cmd"><strong>Waiting for review or continuation</strong><p>${esc(e.reason)}</p><p><a href="#scope">Review discovered hosts in Scope</a></p></div>`;
    return `<div class="cmd"><strong>Run stopped · ${esc(date(e.at))}</strong><p>${esc(e.reason)}</p></div>`;
  };
  box.innerHTML=run?`<div class="cmd"><strong>Run ${esc(run.id)}</strong><p>${['group','discover-group'].includes(run.mode)?'Group':'Host'}: ${esc(run.hostName||run.hostIp)} ${run.hostIp?'('+esc(run.hostIp)+')':''} · Model: ${esc(run.model)} · Started: ${esc(date(run.startedAt))}</p><p>Scope: ${esc((run.scope?.cidrs||[]).join(', '))} · ${esc((run.scope?.domains||[]).join(', '))} · ${esc(run.scope?.matchMode||'and').toUpperCase()}</p></div>`+run.events.map(eventHtml).join(''):'<div class="empty">No autonomous decisions recorded yet.</div>';
  if(run?.status==='awaiting-approval'&&run.pendingProposal){
    const p=run.pendingProposal;
    box.insertAdjacentHTML('beforeend',`<div class="cmd"><strong>Human review required before execution</strong><p>Selected host: ${esc(p.hostName||p.hostIp)} (${esc(p.hostIp)})</p><p>Review the exact command, every destination, required privilege, possible side effect, and credential exposure. Approved commands run as the Yagura server user without an implicit shell.</p><pre>${esc(p.command)}</pre><p>Why: ${esc(p.reason)}</p><p>Expected evidence: ${esc(p.expectedEvidence)}</p><p>Review notes: ${esc(p.reviewNotes||'Not supplied by the model.')}</p><div class="field"><label for="autonomyRevisionInstruction">Correction instruction</label><textarea id="autonomyRevisionInstruction" rows="3" maxlength="500" placeholder="For example: use smbclient without credentials to list shares"></textarea></div><div class="toolbar"><button class="btn" id="autonomyRevise">Ask AI to revise</button></div><label class="check"><input id="autonomyProposalAuthorized" type="checkbox"><span>I reviewed this exact command, its destinations, privileges, side effects, and credentials; I authorize Yagura to run it under the saved scope.</span></label><div class="toolbar"><button class="btn primary" id="autonomyApprove">Approve and run this revision</button></div><p class="status" id="autonomyReviewState"></p></div>`);
    $('#autonomyRevise').onclick=async()=>{const instruction=$('#autonomyRevisionInstruction').value.trim();if(instruction.length<5){$('#autonomyReviewState').textContent='Describe the correction in at least five characters.';return;}$('#autonomyRevise').disabled=true;$('#autonomyApprove').disabled=true;$('#autonomyReviewState').textContent='AI is revising the command…';try{await post('/api/autonomy/revise',{runId:run.id,proposalId:p.id,revision:p.revision,instruction,authorizedScope:checkScope()});await loadAutonomyHistory();}catch(e){$('#autonomyReviewState').textContent=e.message;$('#autonomyRevise').disabled=false;$('#autonomyApprove').disabled=false;}};
    $('#autonomyApprove').onclick=async()=>{if(!$('#autonomyProposalAuthorized').checked){$('#autonomyReviewState').textContent='Review and authorize this exact command first.';return;}$('#autonomyRevise').disabled=true;$('#autonomyApprove').disabled=true;$('#autonomyReviewState').textContent='Starting the approved check…';try{await post('/api/autonomy/approve',{runId:run.id,proposalId:p.id,revision:p.revision,expectedCommand:p.command,authorizedScope:checkScope(),authorized:true});await loadAutonomyHistory();}catch(e){$('#autonomyReviewState').textContent=e.message;$('#autonomyRevise').disabled=false;$('#autonomyApprove').disabled=false;}};
  }
  wireRefs(box);
}
function autonomySummaries(){const run=autonomyRuns.find(r=>r.id===autonomyCurrent);if(!run)return;const rows=$('#autonomyTimeline').children;run.events.forEach((e,i)=>{if(e.type==='check'&&e.summary&&rows[i+1]){const p=document.createElement('p');p.textContent='Response excerpt: '+e.summary;rows[i+1].append(p);}});}
async function loadAutonomyHistory(){try{const data=await api('/api/autonomy');const limits=data.limits||{maxChecks:3,maxSeconds:180,groupMaxChecks:12,groupMaxSeconds:600};$('#autonomyLimitBadge').textContent=(limits.maxChecks==null?'NO CHECK COUNT LIMIT':'MAX '+limits.maxChecks+' CHECKS')+' · '+limits.maxSeconds+' SECONDS (SINGLE)';$('#autonomyAuthorizeText').textContent=limits.maxChecks==null?'I authorize read-only catalog checks on this host until the time limit, a stop request, or human review of a new proposal, under the saved scope.':`I authorize up to ${limits.maxChecks} read-only checks on this host under the saved scope.`;$('#autonomyGroupAuthorizeText').textContent=`I authorize up to ${limits.groupMaxChecks} read-only catalog checks across these hosts within ${limits.groupMaxSeconds} seconds of active execution under the saved scope. Any additional command needs separate approval.`;const before=autonomyRuns.flatMap(r=>r.events.filter(e=>e.type==='check').flatMap(e=>e.evidenceIds||[])).join(','),wasRunning=autonomyRuns.some(r=>r.status==='running');autonomyRuns=data.runs||[];const after=autonomyRuns.flatMap(r=>r.events.filter(e=>e.type==='check').flatMap(e=>e.evidenceIds||[])).join(',');if(scopeLoaded&&checkScope()&&(before!==after||wasRunning&&!autonomyRuns.some(r=>r.status==='running')))await refreshFindings();if(wasRunning&&!autonomyRuns.some(r=>r.status==='running')&&checkScope())await loadPendingDiscovery();renderAutonomy();autonomySummaries();}catch(e){$('#autonomyState').textContent=e.message;}}
$('#autonomyHistory').onchange=()=>{autonomyCurrent=$('#autonomyHistory').value;renderAutonomy();autonomySummaries();};
$('#autonomyStart').onclick=async()=>{const hostId=$('#autonomyHost').value;if(!hostId||!checkScope()){$('#autonomyState').textContent='Choose an approved host under the saved scope.';return;}if(!$('#autonomyAuthorized').checked){$('#autonomyState').textContent='Confirm authorization for this run first.';return;}const button=$('#autonomyStart');button.disabled=true;$('#autonomyState').textContent='Starting AI-led run…';try{const run=await post('/api/autonomy/start',{hostId,model:$('#autonomyModel').value,authorizedScope:checkScope(),authorized:true});autonomyCurrent=run.id;$('#autonomyAuthorized').checked=false;await loadAutonomyHistory();}catch(e){$('#autonomyState').textContent=e.message;button.disabled=false;}};
$('#autonomyGroupStart').onclick=async()=>{const hostIds=[...$('#autonomyGroup').selectedOptions].map(o=>o.value);if(hostIds.length<2||hostIds.length>8||!checkScope()){$('#autonomyState').textContent='Choose two to eight approved hosts under the saved scope.';return;}if(!$('#autonomyGroupAuthorized').checked){$('#autonomyState').textContent='Confirm authorization for the selected group first.';return;}const button=$('#autonomyGroupStart');button.disabled=true;$('#autonomyState').textContent='Starting group survey…';try{const run=await post('/api/autonomy/start-group',{hostIds,model:$('#autonomyModel').value,authorizedScope:checkScope(),authorized:true});autonomyCurrent=run.id;$('#autonomyGroupAuthorized').checked=false;await loadAutonomyHistory();}catch(e){$('#autonomyState').textContent=e.message;button.disabled=false;}};
$('#autonomyDiscoverStart').onclick=async()=>{if(!checkScope()){$('#autonomyState').textContent='Save an authorized target scope first.';return;}if(!$('#autonomyDiscoverAuthorized').checked){$('#autonomyState').textContent='Confirm authorization for saved-scope discovery first.';return;}const button=$('#autonomyDiscoverStart');button.disabled=true;$('#autonomyState').textContent='Starting scoped discovery…';try{const resolvers=$('#autonomyResolvers').value.split(/[\s,]+/).filter(Boolean),run=await post('/api/autonomy/discover-group',{resolvers,model:$('#autonomyModel').value,authorizedScope:checkScope(),authorized:true});autonomyCurrent=run.id;$('#autonomyDiscoverAuthorized').checked=false;await loadAutonomyHistory();}catch(e){$('#autonomyState').textContent=e.message;button.disabled=false;}};
$('#autonomyDiscoverResume').onclick=async()=>{const run=autonomyRuns.find(r=>['awaiting-host-review','awaiting-discovery'].includes(r.status));if(!run||!$('#autonomyDiscoverAuthorized').checked){$('#autonomyState').textContent='Confirm authorization before continuing discovery or selecting approved hosts.';return;}const button=$('#autonomyDiscoverResume');button.disabled=true;try{await post('/api/autonomy/resume-discovery',{runId:run.id,authorizedScope:checkScope(),authorized:true});$('#autonomyDiscoverAuthorized').checked=false;autonomyCurrent=run.id;await loadAutonomyHistory();}catch(e){$('#autonomyState').textContent=e.message;button.disabled=false;}};
$('#autonomyStop').onclick=async()=>{const active=autonomyRuns.find(r=>['running','awaiting-approval','awaiting-host-review','awaiting-discovery'].includes(r.status));if(!active)return;$('#autonomyStop').disabled=true;try{await post('/api/autonomy/stop',{runId:active.id});$('#autonomyState').textContent=active.status==='running'?'Stop requested; waiting for the current check.':'Pending review declined.';await loadAutonomyHistory();}catch(e){$('#autonomyState').textContent=e.message;}};
let activityData={active:[],recent:[]},activityError='',activityLoading=false,activityFocus=null;
function activityElapsed(started){if(!started)return '';const seconds=Math.max(0,Math.floor((Date.now()-Date.parse(started))/1000));return Number.isFinite(seconds)?seconds<60?seconds+'s':Math.floor(seconds/60)+'m '+String(seconds%60).padStart(2,'0')+'s':'';}
function activityCard(row){
  const progress=row.progress,hasProgress=progress&&Number.isFinite(progress.completed)&&Number.isFinite(progress.total)&&progress.total>0;
  const pct=hasProgress?Math.min(100,Math.max(0,Math.round(100*progress.completed/progress.total))):0;
  const label=row.state==='running'?'Running':row.outcome==='no-response'?'No response':row.outcome==='completed'?'Completed':row.outcome==='stopped'?'Stopped':'Failed';
  return '<article class="activity-entry"><strong>'+esc(row.title||row.kind)+'</strong><p class="activity-meta">'+esc(label)+' · '+esc(row.kind)+(row.target?' · '+esc(row.target):'')+(row.state==='running'?' · '+esc(activityElapsed(row.startedAt)):' · '+esc(date(row.endedAt)))+'</p>'+(row.detail?'<p>'+esc(row.detail)+'</p>':'')+(row.command?'<code>'+esc(row.command)+'</code>':'')+(hasProgress?'<p class="activity-meta">'+esc(progress.completed)+' / '+esc(progress.total)+' '+esc(progress.unit||'steps')+'</p><div class="activity-progress" aria-label="'+esc(progress.completed)+' of '+esc(progress.total)+' '+esc(progress.unit||'steps')+'"><span style="width:'+pct+'%"></span></div>':'')+'</article>';
}
function renderActivity(){
  const local=[];
  if(autoRunning&&autoPlan)local.push({kind:'browser run',title:'Short automatic check run',target:recordLabel(findings.find(f=>f.id===autoPlan.hostId)||{title:'Selected host'}),command:autoCurrentCheck,detail:$('#autoState').textContent,progress:{completed:$('#autoResults').children.length,total:autoPlan.checks.length,unit:'checks'},state:'running',startedAt:autoStartedAt});
  if(!$('#stopScanBtn').disabled)local.push({kind:'browser run',title:'Scoped discovery sequence',target:$('#scanTarget').value,detail:$('#scanState').textContent,state:'running'});
  const active=[...local,...activityData.active],count=active.length;
  $('#activityToggleText').textContent=activityError?'Activity ?':count?count+' running':'Activity';
  $('#activityPulse').classList.toggle('running',!!count&&!activityError);
  $('#activityPulse').classList.toggle('error',!!activityError);
  $('#activitySummary').textContent=activityError?'Status unavailable: '+activityError:count?count+' operation(s) in progress.':'No operations running.';
  $('#activityActive').innerHTML=activityError?'<div class="empty">Live status is unavailable. Retrying…</div>':active.length?active.map(activityCard).join(''):'<div class="empty">Nothing is running right now.</div>';
  $('#activityRecent').innerHTML=activityData.recent.length?activityData.recent.map(activityCard).join(''):'<div class="empty">No recent server activity.</div>';
}
async function refreshActivity(){if(activityLoading)return;activityLoading=true;try{activityData=await api('/api/activity');activityError='';}catch(e){activityError=e.message;}finally{activityLoading=false;renderActivity();}}
function openActivity(){activityFocus=document.activeElement;$('#activityBackdrop').hidden=false;$('#activityDrawer').hidden=false;document.body.classList.add('activity-open');$('#activityToggle').setAttribute('aria-expanded','true');renderActivity();$('#activityClose').focus();}
function closeActivity(){$('#activityBackdrop').hidden=true;$('#activityDrawer').hidden=true;document.body.classList.remove('activity-open');$('#activityToggle').setAttribute('aria-expanded','false');(activityFocus||$('#activityToggle')).focus();}
$('#activityToggle').onclick=()=>$('#activityDrawer').hidden?openActivity():closeActivity();
$('#activityClose').onclick=closeActivity;
$('#activityBackdrop').onclick=closeActivity;
document.addEventListener('keydown',event=>{if($('#activityDrawer').hidden||$('#reviewDialog').open)return;if(event.key==='Escape'){event.preventDefault();closeActivity();}else if(event.key==='Tab'){event.preventDefault();$('#activityClose').focus();}});
load();loadAutonomyHistory();loadCheckProposals();refreshActivity();setInterval(()=>{refreshActivity();if(autonomyRuns.some(r=>r.status==='running'))loadAutonomyHistory();},2500);
